DROP TABLE IF EXISTS `faculty`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `faculty` (
  `faculty_ID` int NOT NULL,
  `user_Type` enum('Student','Faculty','Admin','StatStaff') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Faculty',
  `office_ID` int NOT NULL,
  `Specialty` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `faculty_Rank` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `faculty_Type` enum('Full-Time','Part-Time') COLLATE utf8mb4_unicode_ci NOT NULL,
  `no_of_Classes` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`faculty_ID`),
  UNIQUE KEY `uq_Faculty_ID_type` (`faculty_ID`,`faculty_Type`),
  UNIQUE KEY `uq_Faculty_office` (`office_ID`),
  KEY `faculty_ID` (`faculty_ID`,`user_Type`),
  CONSTRAINT `faculty_ibfk_1` FOREIGN KEY (`faculty_ID`, `user_Type`) REFERENCES `user` (`user_ID`, `user_Type`),
  CONSTRAINT `faculty_ibfk_2` FOREIGN KEY (`office_ID`) REFERENCES `office` (`office_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
