  `student_Type` enum('Undergraduate','Graduate') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Graduate',
  `dept_ID` int NOT NULL,
  `Program` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
