  CONSTRAINT `graduate_student_ibfk_2` FOREIGN KEY (`dept_ID`) REFERENCES `department` (`dept_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
