CREATE TABLE `login` (
  `user_ID` int NOT NULL,
  `user_Email` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `user_Password` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `no_Of_Tries` int NOT NULL DEFAULT '0',
  `lock_var` tinyint(1) NOT NULL DEFAULT '0',
  `user_Type` enum('Student','Faculty','Admin','StatStaff') COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`user_ID`),
  UNIQUE KEY `user_Email` (`user_Email`),
  KEY `user_ID` (`user_ID`,`user_Type`),
  CONSTRAINT `login_ibfk_1` FOREIGN KEY (`user_ID`, `user_Type`) REFERENCES `user` (`user_ID`, `user_Type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
