  CONSTRAINT `student_history_ibfk_3` FOREIGN KEY (`course_ID`) REFERENCES `course` (`course_ID`),
  CONSTRAINT `student_history_ibfk_4` FOREIGN KEY (`semester_ID`) REFERENCES `semester` (`semester_ID`),
